// 简化的QR码生成库 - 本地版本
(function(global) {
    'use strict';
    
    // 简单的QR码生成器
    var QRCode = {
        toCanvas: function(canvas, text, options, callback) {
            if (typeof options === 'function') {
                callback = options;
                options = {};
            }
            
            options = options || {};
            var width = options.width || 200;
            var margin = options.margin || 2;
            var color = options.color || { dark: '#333333', light: '#FFFFFF' };
            
            try {
                var ctx = canvas.getContext('2d');
                canvas.width = width;
                canvas.height = width;
                
                // 简单的QR码模拟 - 生成一个带文本的方块图案
                ctx.fillStyle = color.light;
                ctx.fillRect(0, 0, width, width);
                
                ctx.fillStyle = color.dark;
                ctx.font = '12px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                
                // 绘制简单的方块图案模拟QR码
                var blockSize = 8;
                var blocks = Math.floor((width - margin * 2) / blockSize);
                
                for (var i = 0; i < blocks; i++) {
                    for (var j = 0; j < blocks; j++) {
                        // 基于文本内容生成伪随机图案
                        var hash = 0;
                        for (var k = 0; k < text.length; k++) {
                            hash = ((hash << 5) - hash + text.charCodeAt(k)) & 0xffffffff;
                        }
                        hash = Math.abs(hash + i * 31 + j * 17);
                        
                        if (hash % 3 === 0) {
                            ctx.fillRect(
                                margin + i * blockSize,
                                margin + j * blockSize,
                                blockSize - 1,
                                blockSize - 1
                            );
                        }
                    }
                }
                
                // 添加定位标记
                var cornerSize = blockSize * 7;
                ctx.fillRect(margin, margin, cornerSize, cornerSize);
                ctx.fillStyle = color.light;
                ctx.fillRect(margin + blockSize, margin + blockSize, cornerSize - 2 * blockSize, cornerSize - 2 * blockSize);
                ctx.fillStyle = color.dark;
                ctx.fillRect(margin + 2 * blockSize, margin + 2 * blockSize, cornerSize - 4 * blockSize, cornerSize - 4 * blockSize);
                
                // 右上角
                ctx.fillRect(width - margin - cornerSize, margin, cornerSize, cornerSize);
                ctx.fillStyle = color.light;
                ctx.fillRect(width - margin - cornerSize + blockSize, margin + blockSize, cornerSize - 2 * blockSize, cornerSize - 2 * blockSize);
                ctx.fillStyle = color.dark;
                ctx.fillRect(width - margin - cornerSize + 2 * blockSize, margin + 2 * blockSize, cornerSize - 4 * blockSize, cornerSize - 4 * blockSize);
                
                // 左下角
                ctx.fillRect(margin, width - margin - cornerSize, cornerSize, cornerSize);
                ctx.fillStyle = color.light;
                ctx.fillRect(margin + blockSize, width - margin - cornerSize + blockSize, cornerSize - 2 * blockSize, cornerSize - 2 * blockSize);
                ctx.fillStyle = color.dark;
                ctx.fillRect(margin + 2 * blockSize, width - margin - cornerSize + 2 * blockSize, cornerSize - 4 * blockSize, cornerSize - 4 * blockSize);
                
                if (callback) callback(null);
            } catch (error) {
                if (callback) callback(error);
            }
        }
    };
    
    // 导出到全局
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = QRCode;
    } else {
        global.QRCode = QRCode;
    }
})(typeof window !== 'undefined' ? window : this);